import{H as e,V as t,et as n,j as r}from"./chunks/framework.ByEJxCeM.js";import"./chunks/assets.Capd0F6S.js";var i=JSON.parse(`{"title":"Linux概述","description":"","frontmatter":{},"headers":[],"relativePath":"java/deployment/linux/overview.md","filePath":"java/deployment/linux/overview.md"}`),a={name:`java/deployment/linux/overview.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="linux概述" tabindex="-1">Linux概述 <a class="header-anchor" href="#linux概述" aria-label="Permalink to “Linux概述”">​</a></h1><h2 id="主流操作系统" tabindex="-1">主流操作系统 <a class="header-anchor" href="#主流操作系统" aria-label="Permalink to “主流操作系统”">​</a></h2><p>不同领域的主流操作系统，主要分为以下这么几类： 桌面操作系统、服务器操作系统、移动设备操作系统、嵌入式操作系统。接下来，这几个领域中，代表性的操作系统是那些?</p><p><strong>1). 桌面操作系统</strong></p><p><strong>2). 服务器操作系统</strong></p><p><strong>3). 移动设备操作系统</strong></p><h2 id="linux系统版本" tabindex="-1">Linux系统版本 <a class="header-anchor" href="#linux系统版本" aria-label="Permalink to “Linux系统版本”">​</a></h2><p>Linux系统的版本分为两种，分别是： 内核版 和 发行版。</p><p><strong>1). 内核版</strong></p><ul><li><p>由Linus Torvalds及其团队开发、维护</p></li><li><p>免费、开源</p></li><li><p>负责控制硬件</p></li></ul><p><strong>2). 发行版</strong></p><ul><li><p>基于Linux内核版进行扩展</p></li><li><p>由各个Linux厂商开发、维护</p></li><li><p>有收费版本和免费版本</p></li></ul><p>我们使用Linux操作系统，实际上选择的是Linux的发行版本。在linux系统中，有各种各样的发行版本，具体如下：</p><p><img src="/blog-notes/assets/image-14.BWxSrVOF.png" alt="imagepng" width="1352" height="430"></p><p>除了上述罗列出来的发行版，还有很多Linux发行版，这里，我们就不再一一列举了。</p><h2 id="系统安装" tabindex="-1">系统安装 <a class="header-anchor" href="#系统安装" aria-label="Permalink to “系统安装”">​</a></h2><h3 id="安装方式" tabindex="-1">安装方式 <a class="header-anchor" href="#安装方式" aria-label="Permalink to “安装方式”">​</a></h3><p>Linux系统的安装方式，主要包含以下两种：</p><p><img src="/blog-notes/assets/image-72.BU8DkORa.png" alt="imagepng" width="549" height="254"></p><p><img src="/blog-notes/assets/image-43.nJLrpJ3z.png" alt="imagepng" width="1353" height="153"></p><p><strong>虚拟机</strong>（Virtual Machine）指通过软件模拟的具有完整硬件系统功能、运行在完全隔离环境中的完整计算机系统。常用虚拟机软件：</p><ul><li><p>VMWare</p></li><li><p>VirtualBox</p></li><li><p>VMLite WorkStation</p></li><li><p>Qemu</p></li><li><p>HopeddotVOS</p></li></ul><p>那么我们就可以在课程中将Linux操作系统安装在虚拟机中，我们课上选择的虚拟机软件是<strong>VMware</strong>。</p><h3 id="安装vmware" tabindex="-1">安装VMware <a class="header-anchor" href="#安装vmware" aria-label="Permalink to “安装VMware”">​</a></h3><p><img src="/blog-notes/assets/image-87.CFihlzj5.png" alt="imagepng" width="492" height="43"></p><p>在我们的课程资料中提供了VMware的安装程序。找到课程资料中的 Vmware的安装包（exe文件），然后双击下一步下一步的安装即可。</p><p><img src="/blog-notes/assets/image-68.BvFpKA4O.png" alt="imagepng" width="1026" height="178"></p><p><strong>备注：如果之前安装过，就不用安装了。不要卸载！！！！ 不要卸载！！！！ 不要卸载！！！！</strong></p><p><strong>安装步骤:</strong></p><p><img src="/blog-notes/assets/image-83.BKjDeKzA.png" alt="imagepng" width="1645" height="406"></p><p><img src="/blog-notes/assets/image-59.CJEWBfpu.png" alt="imagepng" width="1646" height="409"></p><p>以上就是VMware在安装时的每一步操作，基本上就是点击 &quot;下一步&quot; 一直进行安装。</p><h3 id="挂载linux系统" tabindex="-1">挂载Linux系统 <a class="header-anchor" href="#挂载linux系统" aria-label="Permalink to “挂载Linux系统”">​</a></h3><p>**1). 打开Vmware虚拟机，打开 <strong><strong><code>编辑</code></strong></strong> -&gt; **<strong><code>虚拟网络编辑器(N)...</code></strong></p><p><img src="/blog-notes/assets/image-22.Cq-jhaP7.png" alt="imagepng" width="787" height="539"></p><p>选择 <code>NAT模式</code>，然后选择右下角的 <code>更改设置</code>。</p><p><img src="/blog-notes/assets/image-39.CpCbM38L.png" alt="imagepng" width="698" height="681"></p><p>设置子网IP为 <strong><code>192.168.100.0</code></strong>，然后选择 <code>应用</code> -&gt; <code>确定</code>。</p><p><img src="/blog-notes/assets/image-88.CpdTu9D3.png" alt="imagepng" width="815" height="749"></p><p><strong>2). 解压 <strong><strong><code>资料/Linux</code></strong></strong><code>镜像</code><strong><strong><code>/CentOS7-1.zip</code></strong></strong> 到一个比较大的磁盘中 (没有中文的目录)。</strong></p><p><img src="/blog-notes/assets/image-44.BPS6mbJC.png" alt="imagepng" width="1016" height="174"></p><p><strong>3). 打开解压目录，双击 <strong><strong><code>.vmx</code></strong></strong> 文件，选择以 <strong><strong><code>Vmware Workstation</code></strong></strong> 打开这个文件。</strong></p><p><img src="/blog-notes/assets/image-13.CZ0yZYoU.png" alt="imagepng" width="970" height="521"></p><p><strong>4). 挂载完毕之后，启动Linux服务器。</strong></p><p><img src="/blog-notes/assets/image-90.C2L4zW2I.png" alt="imagepng" width="893" height="802"></p><p>启动过程中，如果出现如下界面，选择 <strong><code>我已移动该虚拟机</code></strong>。</p><p><img src="/blog-notes/assets/image-11.BSGygxIn.png" alt="imagepng" width="1028" height="449"></p><p>**5). 启动完毕之后，登录服务器。 输入用户名：<strong><strong><code>root</code></strong></strong>，密码：<strong><strong><code>1234</code></strong></strong> **<strong>（注意：linux系统输入密码是不显示的，输入完毕，回车即可登录）</strong></p><p><img src="/blog-notes/assets/image-58.Boby0g-U.png" alt="imagepng" width="1022" height="292"></p><h2 id="安装ssh连接工具" tabindex="-1">安装SSH连接工具 <a class="header-anchor" href="#安装ssh连接工具" aria-label="Permalink to “安装SSH连接工具”">​</a></h2><h3 id="ssh连接工具介绍" tabindex="-1">SSH连接工具介绍 <a class="header-anchor" href="#ssh连接工具介绍" aria-label="Permalink to “SSH连接工具介绍”">​</a></h3><p>Linux已经安装并且配置好了，接下来我们要来学习Linux的基本操作指令。而在学习之前，我们还需要做一件事情，由于我们企业开发时，Linux服务器一般都是在远程的机房部署的，我们要操作服务器，不会每次都跑到远程的机房里面操作，而是会直接通过SSH连接工具进行连接操作。</p><p><img src="/blog-notes/assets/image-81.BiDY4y0W.png" alt="imagepng" width="849" height="201"></p><p>SSH（Secure Shell），建立在应用层基础上的安全协议。常用的SSH连接工具:</p><p><img src="/blog-notes/assets/image-47.Czr-Fk_m.png" alt="imagepng" width="1351" height="415"></p><h3 id="finalshell安装" tabindex="-1">FinalShell安装 <a class="header-anchor" href="#finalshell安装" aria-label="Permalink to “FinalShell安装”">​</a></h3><p>在课程资料中，提供了finalShell的安装包（<strong>&quot;资料/03. 远程连接工具&quot;</strong>）。</p><p><img src="data:image/png;base64," alt="imagepng" width="240" height="47"></p><p>双击.exe文件，然后进行正常的安装即可。</p><p><img src="/blog-notes/assets/image-52.BWgIC5fO.png" alt="imagepng" width="672" height="485"></p><h3 id="连接linux" tabindex="-1">连接Linux <a class="header-anchor" href="#连接linux" aria-label="Permalink to “连接Linux”">​</a></h3><ul><li>打开FinalShell，选择SSH连接。</li></ul><p><img src="/blog-notes/assets/image-6.Blrbg7RO.png" alt="imagepng" width="1022" height="390"></p><ul><li>连接服务器，输入服务器的信息，IP固定的：<strong><code>192.168.100.128</code></strong>，用户名：<strong><code>root</code></strong>，密码：<strong><code>1234</code></strong></li></ul><p><img src="/blog-notes/assets/image-75.Fn8joLui.png" alt="imagepng" width="801" height="734"></p><ul><li>配置完毕后,双击即可连接服务器。</li></ul><p><img src="/blog-notes/assets/image-71.BsUDKlCC.png" alt="imagepng" width="1922" height="745"></p><p><img src="/blog-notes/assets/image-5.DkdufFDF.png" alt="imagepng" width="1920" height="773"></p><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to “目录结构”">​</a></h2><p>登录到Linux系统之后，我们需要先来熟悉一下Linux的目录结构。在Linux系统中，也是存在目录的概念的，但是Linux的目录结构和Windows的目录结构是存在比较多的差异的 在Windows目录下，是一个一个的盘符(C盘、D盘、E盘)，目录是归属于某一个盘符的。Linux系统中的目录有以下特点：</p><ul><li><p><strong>/ 是所有目录的顶点</strong></p></li><li><p><strong>目录结构像一颗倒挂的树</strong></p></li></ul><p><strong>Linux 和 Windows的目录结构对比:</strong></p><p><img src="/blog-notes/assets/image-67.DcpxNl_x.png" alt="imagepng" width="884" height="505"></p><p>Linux的目录结构，如下：</p><p><img src="/blog-notes/assets/image-21.BX3IZIw2.png" alt="imagepng" width="624" height="327"></p><p>根目录 / 下各个目录的作用及含义说明:</p>`,76)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};